import {getDesign} from './design-state.js';
import {scene,robot,set,state,draftFromState,THREE} from './app.js';
const DEG=Math.PI/180,wrap=a=>Math.atan2(Math.sin(a),Math.cos(a));let scenario=getDesign().rehearsal,omega=scenario.turnSpeedDegps*DEG;let route=scenario.route.map(p=>({...p,heading:p.headingDeg})),timeline=[],playing=false,time=0,total=0,last=0,exposure=0;
const enemy=new THREE.Group();scene.add(enemy);for(const [w,h,col] of [[.86,.15,0xa53e57],[.65,.55,0xd46272]]){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,w),new THREE.MeshStandardMaterial({color:col,transparent:true,opacity:.8}));mesh.position.y=h/2+.04;enemy.add(mesh)}const hit=new THREE.Mesh(new THREE.SphereGeometry(.09,16,12),new THREE.MeshBasicMaterial({color:0xff4d40}));scene.add(hit);hit.visible=false;let path=null;
function overlaps(a,b){const axes=[[Math.cos(a.heading),Math.sin(a.heading)],[-Math.sin(a.heading),Math.cos(a.heading)],[Math.cos(b.heading),Math.sin(b.heading)],[-Math.sin(b.heading),Math.cos(b.heading)]];const own=[[Math.cos(a.heading),Math.sin(a.heading)],[-Math.sin(a.heading),Math.cos(a.heading)]],other=[[Math.cos(b.heading),Math.sin(b.heading)],[-Math.sin(b.heading),Math.cos(b.heading)]];return axes.every(n=>{const d=Math.abs((b.x-a.x)*n[0]+(b.y-a.y)*n[1]);const support=(arr,obj)=>arr.reduce((s,v,i)=>s+(i===0?(obj.hx??.43):(obj.hy??.43))*Math.abs(v[0]*n[0]+v[1]*n[1]),0);return d<support(own,a)+support(other,b)})}
function build(){timeline=[];let p={...route[0]};const speed=Number(document.querySelector('#speed').value);function add(q,duration,type){if(duration>1e-8)timeline.push({a:{...p},b:{...q},duration,type});p={...q}}for(const q of route.slice(1)){const dist=Math.hypot(q.x-p.x,q.y-p.y);if(dist>1e-8){const bearing=Math.atan2(q.y-p.y,q.x-p.x)/DEG;add({...p,heading:bearing},Math.abs(wrap((bearing-p.heading)*DEG))/omega,'Turn to travel');add({...q,heading:bearing},dist/speed,'Drive')}add({...q},Math.abs(wrap((q.heading-p.heading)*DEG))/omega,'Face action');if(q.action!=='none')add({...q},scenario.actionDurations[q.action],q.action==='pickup'?'Pickup attempt — assumed wait':'Shot attempt — assumed wait')}total=timeline.reduce((s,x)=>s+x.duration,0);const drive=timeline.filter(s=>s.type==='Drive').reduce((s,x)=>s+x.duration,0),turn=timeline.filter(s=>s.type.startsWith('Turn')||s.type==='Face action').reduce((s,x)=>s+x.duration,0),action=total-drive-turn;document.querySelector('#routeList').innerHTML=route.map((r,i)=>`${i+1}. (${r.x.toFixed(2)}, ${r.y.toFixed(2)}) m / ${r.heading.toFixed(0)}° / ${r.action}`).join('<br>')+`<br><br>Budget ${total.toFixed(1)} s = drive ${drive.toFixed(1)} + turn ${turn.toFixed(1)} + actions ${action.toFixed(1)}.`;if(path){scene.remove(path);path.geometry.dispose();path.material.dispose()}path=new THREE.Line(new THREE.BufferGeometry().setFromPoints(route.map(r=>new THREE.Vector3(r.x,.02,r.y))),new THREE.LineDashedMaterial({color:0xffd38e,dashSize:.12,gapSize:.08}));path.computeLineDistances();scene.add(path);window.rehearsalPlan={route,timeline,total,drive,turn,action}}
function sample(t){let k=0;for(const seg of timeline){if(t<=k+seg.duration){const f=(t-k)/seg.duration;return{x:seg.a.x+(seg.b.x-seg.a.x)*f,y:seg.a.y+(seg.b.y-seg.a.y)*f,heading:wrap(seg.a.heading*DEG+wrap((seg.b.heading-seg.a.heading)*DEG)*f)/DEG,stage:seg.type}}k+=seg.duration}return{...route.at(-1),stage:'Rehearsal complete — outcomes not simulated'}}
function show(dt=0){const enabled=document.querySelector('#opponent').checked;enemy.visible=enabled;const o=scenario.opponent,cycle=(time%o.periodS)/o.periodS;const op={x:o.x,y:o.yMin+(cycle<.5?cycle*2:2-cycle*2)*(o.yMax-o.yMin),heading:Math.PI/2,hx:o.footprintM/2,hy:o.footprintM/2};enemy.position.set(op.x,0,op.y);enemy.rotation.y=-op.heading;const dims=draftFromState().design.parameters;enemy.scale.set(o.footprintM/.86,1,o.footprintM/.86);const own={x:state.x,y:state.y,heading:state.heading*DEG,hx:dims.frameLengthM/2+dims.bumperDepthM,hy:dims.frameWidthM/2+dims.bumperDepthM};const overlap=enabled&&overlaps(own,op);hit.visible=overlap;if(overlap){hit.position.set((own.x+op.x)/2,.22,(own.y+op.y)/2);exposure+=dt}const stage=sample(time).stage;document.querySelector('#routeStatus').innerHTML=`${time.toFixed(1)} / ${total.toFixed(1)} s — ${stage}<br><span class="${overlap?'bad':'muted'}">${overlap?'Footprints overlap: potential contact exposure':'No scripted footprint overlap now'}</span><br>Overlap time ${exposure.toFixed(2)} s (not damage or impact duration).`;window.rehearsalState={playing,time,total,stage,overlap,exposure,opponent:op}}
document.querySelector('#rehearse').onclick=()=>{build();time=0;exposure=0;playing=timeline.length>0;set(route[0]);show()};document.querySelector('#pauseRoute').onclick=()=>{playing=false;show()};document.querySelector('#addPose').onclick=()=>{playing=false;const ids=new Set(route.map(p=>p.id));let n=1;while(ids.has('pose-'+n))n++;route.push({id:'pose-'+n,x:state.x,y:state.y,heading:state.heading,action:document.querySelector('#action').value});build();show()};document.querySelector('#clearRoute').onclick=()=>{playing=false;time=0;exposure=0;route=[{id:'pose-1',x:state.x,y:state.y,heading:state.heading,action:'none'}];build();show()};document.querySelector('#speed').oninput=()=>{playing=false;document.querySelector('#speedVal').textContent=Number(document.querySelector('#speed').value).toFixed(2)+' m/s';build();show()};document.querySelector('#opponent').onchange=()=>show();for(const id of['x','y','heading'])document.querySelector('#'+id).addEventListener('input',()=>{playing=false;show()});for(const id of['reset','pickup'])document.querySelector('#'+id).addEventListener('click',()=>{playing=false;show()});build();show();function animate(now){const dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(playing){time=Math.min(total,time+dt);const p=sample(time);set({x:p.x,y:p.y,heading:p.heading});if(time>=total)playing=false;show(dt)}requestAnimationFrame(animate)}requestAnimationFrame(animate);window.blockoutOverlapTest=overlaps;window.rehearsalApi={stop(){playing=false;show()},read(){return{...structuredClone(scenario),route:route.map((p,i)=>({id:p.id??('pose-'+(i+1)),x:p.x,y:p.y,headingDeg:p.heading,action:p.action})),driveSpeedMps:Number(document.querySelector('#speed').value),opponent:{...scenario.opponent,enabled:document.querySelector('#opponent').checked}}},load(value){playing=false;time=0;exposure=0;scenario=structuredClone(value);omega=scenario.turnSpeedDegps*DEG;route=value.route.map(p=>({...p,heading:p.headingDeg}));const el=document.querySelector('#speed');el.min=Math.min(Number(el.min),value.driveSpeedMps);el.max=Math.max(Number(el.max),value.driveSpeedMps);el.step='any';el.value=value.driveSpeedMps;document.querySelector('#speedVal').textContent=value.driveSpeedMps.toFixed(2)+' m/s';document.querySelector('#opponent').checked=value.opponent.enabled;build();show()}};window.rehearsalSample=sample;window.rehearsalReady=true;
